-- Modern chandelier offer with the showroom's own photos (40% off, average 30 KWD before the sale).
-- The 8 stock-photo placeholders from 20261013110000 are hidden (not deleted).
BEGIN;

UPDATE public.categories SET is_active = true WHERE slug = 'chandelier';
UPDATE public.products SET is_active = false WHERE sku IN ('MCH-01','MCH-02','MCH-03','MCH-04','MCH-05','MCH-06','MCH-07','MCH-08');

CREATE TEMP TABLE chandelier_offer (sku text, slug text, name_en text, name_ar text, base_price numeric, sale_price numeric,
  description_en text, description_ar text, short_en text, short_ar text, image_url text) ON COMMIT DROP;

INSERT INTO chandelier_offer VALUES
('MCH-11', 'black-lace-cylinder-cluster-chandelier', 'Black Lace Cylinder 3-Light Cluster Chandelier', 'ثريا عنقودية ثلاثية بأسطوانات دانتيل سوداء', 20.000, 12.000, 'Three black lace-cut metal cylinders on a round canopy, casting patterned light; ideal over dining tables and stair voids. Photographed in our showroom in Hawalli; delivery across Kuwait. Ask us on WhatsApp for sizes and finishes.', 'ثلاث أسطوانات معدنية سوداء بنقشة الدانتيل على قاعدة دائرية تنشر ضوءاً منقوشاً، مثالية فوق طاولات الطعام وفراغات الدرج. مصوّرة في معرضنا في حولي مع التوصيل لجميع مناطق الكويت. تواصل معنا عبر واتساب للمقاسات والألوان.', 'Three black lace-cut metal cylinders on a round canopy, casting patterned light; ideal over dining tables and stair voids.', 'ثلاث أسطوانات معدنية سوداء بنقشة الدانتيل على قاعدة دائرية تنشر ضوءاً منقوشاً، مثالية فوق طاولات الطعام وفراغات الدرج.', 'https://yubebbfsmlopmnluajgf.supabase.co/storage/v1/object/public/product-images/chandeliers/black-lace-cylinder-cluster.jpg'),
('MCH-12', 'gold-silver-lace-globe-cluster-chandelier', 'Gold & Silver Lace Globe Cluster Chandelier', 'ثريا عنقودية بكرات دانتيل ذهبي وفضي', 22.000, 13.250, 'A cascade of gold and silver lace globes hung at different heights for a warm, sparkling glow. Photographed in our showroom in Hawalli; delivery across Kuwait. Ask us on WhatsApp for sizes and finishes.', 'مجموعة من كرات الدانتيل الذهبية والفضية معلّقة على ارتفاعات مختلفة لتوهج دافئ ولامع. مصوّرة في معرضنا في حولي مع التوصيل لجميع مناطق الكويت. تواصل معنا عبر واتساب للمقاسات والألوان.', 'A cascade of gold and silver lace globes hung at different heights for a warm, sparkling glow.', 'مجموعة من كرات الدانتيل الذهبية والفضية معلّقة على ارتفاعات مختلفة لتوهج دافئ ولامع.', 'https://yubebbfsmlopmnluajgf.supabase.co/storage/v1/object/public/product-images/chandeliers/lace-globe-cluster.jpg'),
('MCH-13', 'gold-crossed-crystal-ring-chandelier', 'Gold Crossed Crystal Ring Chandelier', 'ثريا حلقتين كريستال متقاطعتين ذهبية', 24.000, 14.500, 'Two crystal-lined gold rings crossing each other; a compact modern piece for bedrooms, entrances and corners. Photographed in our showroom in Hawalli; delivery across Kuwait. Ask us on WhatsApp for sizes and finishes.', 'حلقتان ذهبيتان مكسوتان بالكريستال متقاطعتان، قطعة عصرية مدمجة لغرف النوم والمداخل والزوايا. مصوّرة في معرضنا في حولي مع التوصيل لجميع مناطق الكويت. تواصل معنا عبر واتساب للمقاسات والألوان.', 'Two crystal-lined gold rings crossing each other; a compact modern piece for bedrooms, entrances and corners.', 'حلقتان ذهبيتان مكسوتان بالكريستال متقاطعتان، قطعة عصرية مدمجة لغرف النوم والمداخل والزوايا.', 'https://yubebbfsmlopmnluajgf.supabase.co/storage/v1/object/public/product-images/chandeliers/gold-crossed-crystal-rings.jpg'),
('MCH-14', 'crystal-halo-ring-drum-chandelier', 'Crystal Halo Ring Chandelier with Crystal Drum', 'ثريا هالة كريستال مع أسطوانة كريستال', 26.000, 15.500, 'A glowing crystal halo ring around a central crystal drum, on a black frame. Photographed in our showroom in Hawalli; delivery across Kuwait. Ask us on WhatsApp for sizes and finishes.', 'هالة كريستال مضيئة حول أسطوانة كريستال في المنتصف، على إطار أسود. مصوّرة في معرضنا في حولي مع التوصيل لجميع مناطق الكويت. تواصل معنا عبر واتساب للمقاسات والألوان.', 'A glowing crystal halo ring around a central crystal drum, on a black frame.', 'هالة كريستال مضيئة حول أسطوانة كريستال في المنتصف، على إطار أسود.', 'https://yubebbfsmlopmnluajgf.supabase.co/storage/v1/object/public/product-images/chandeliers/crystal-halo-ring-drum.jpg'),
('MCH-15', 'gold-crystal-loop-chandelier-spheres', 'Gold Crystal Loop Chandelier with Crystal Spheres', 'ثريا حلقة كريستال ذهبية مع كرات كريستال', 28.000, 16.750, 'Gold teardrop and round crystal loops with glowing crystal spheres; a statement piece for living rooms and majlis. Photographed in our showroom in Hawalli; delivery across Kuwait. Ask us on WhatsApp for sizes and finishes.', 'حلقات كريستال ذهبية بشكل قطرة ودائرة مع كرات كريستال مضيئة، قطعة لافتة لغرف المعيشة والمجالس. مصوّرة في معرضنا في حولي مع التوصيل لجميع مناطق الكويت. تواصل معنا عبر واتساب للمقاسات والألوان.', 'Gold teardrop and round crystal loops with glowing crystal spheres; a statement piece for living rooms and majlis.', 'حلقات كريستال ذهبية بشكل قطرة ودائرة مع كرات كريستال مضيئة، قطعة لافتة لغرف المعيشة والمجالس.', 'https://yubebbfsmlopmnluajgf.supabase.co/storage/v1/object/public/product-images/chandeliers/gold-crystal-loop-spheres.jpg'),
('MCH-16', 'gold-triple-crystal-ring-chandelier', 'Gold Triple Crystal Ring Chandelier', 'ثريا ثلاث حلقات كريستال ذهبية', 30.000, 18.000, 'Three crystal-lined gold rings set at angles to each other for a layered, sparkling glow. Photographed in our showroom in Hawalli; delivery across Kuwait. Ask us on WhatsApp for sizes and finishes.', 'ثلاث حلقات ذهبية مكسوة بالكريستال بزوايا مختلفة لتوهج متعدد الطبقات ولامع. مصوّرة في معرضنا في حولي مع التوصيل لجميع مناطق الكويت. تواصل معنا عبر واتساب للمقاسات والألوان.', 'Three crystal-lined gold rings set at angles to each other for a layered, sparkling glow.', 'ثلاث حلقات ذهبية مكسوة بالكريستال بزوايا مختلفة لتوهج متعدد الطبقات ولامع.', 'https://yubebbfsmlopmnluajgf.supabase.co/storage/v1/object/public/product-images/chandeliers/gold-triple-crystal-rings.jpg'),
('MCH-17', 'black-oval-crystal-loops-chandelier', 'Black Oval Crystal Loops Chandelier', 'ثريا حلقات بيضاوية كريستال سوداء', 32.000, 19.250, 'Tall black oval loops edged in crystal, hung vertically; made for stairwells and double-height spaces. Photographed in our showroom in Hawalli; delivery across Kuwait. Ask us on WhatsApp for sizes and finishes.', 'حلقات بيضاوية سوداء طويلة بحواف كريستال معلّقة عمودياً، مصممة لبيت الدرج والأسقف المرتفعة. مصوّرة في معرضنا في حولي مع التوصيل لجميع مناطق الكويت. تواصل معنا عبر واتساب للمقاسات والألوان.', 'Tall black oval loops edged in crystal, hung vertically; made for stairwells and double-height spaces.', 'حلقات بيضاوية سوداء طويلة بحواف كريستال معلّقة عمودياً، مصممة لبيت الدرج والأسقف المرتفعة.', 'https://yubebbfsmlopmnluajgf.supabase.co/storage/v1/object/public/product-images/chandeliers/black-oval-crystal-loops.jpg'),
('MCH-18', 'led-halo-ring-string-web-chandelier', 'LED Halo Ring Chandelier with String Web', 'ثريا هالة LED دائرية بشبكة خيوط', 34.000, 20.500, 'A wide LED halo framing a fine radial string web; soft, even light for living and dining rooms. Photographed in our showroom in Hawalli; delivery across Kuwait. Ask us on WhatsApp for sizes and finishes.', 'هالة LED عريضة تحيط بشبكة خيوط شعاعية دقيقة، ضوء ناعم ومتساوٍ لغرف المعيشة والطعام. مصوّرة في معرضنا في حولي مع التوصيل لجميع مناطق الكويت. تواصل معنا عبر واتساب للمقاسات والألوان.', 'A wide LED halo framing a fine radial string web; soft, even light for living and dining rooms.', 'هالة LED عريضة تحيط بشبكة خيوط شعاعية دقيقة، ضوء ناعم ومتساوٍ لغرف المعيشة والطعام.', 'https://yubebbfsmlopmnluajgf.supabase.co/storage/v1/object/public/product-images/chandeliers/led-halo-ring-string-web.jpg'),
('MCH-19', 'black-interlocking-crystal-rings-chandelier', 'Black Interlocking Crystal Rings Chandelier', 'ثريا حلقات كريستال متشابكة سوداء', 36.000, 21.500, 'Large black rings wrapped in crystal and interlocked into a sculptural form. Photographed in our showroom in Hawalli; delivery across Kuwait. Ask us on WhatsApp for sizes and finishes.', 'حلقات سوداء كبيرة مكسوة بالكريستال ومتشابكة في شكل نحتي. مصوّرة في معرضنا في حولي مع التوصيل لجميع مناطق الكويت. تواصل معنا عبر واتساب للمقاسات والألوان.', 'Large black rings wrapped in crystal and interlocked into a sculptural form.', 'حلقات سوداء كبيرة مكسوة بالكريستال ومتشابكة في شكل نحتي.', 'https://yubebbfsmlopmnluajgf.supabase.co/storage/v1/object/public/product-images/chandeliers/black-interlocking-crystal-rings.jpg'),
('MCH-20', 'crystal-wave-linear-chandelier', 'Crystal Wave Linear Chandelier', 'ثريا خطية كريستال على شكل موجة', 38.000, 22.750, 'A long crystal band twisting like a wave; designed to run along dining tables and kitchen islands. Photographed in our showroom in Hawalli; delivery across Kuwait. Ask us on WhatsApp for sizes and finishes.', 'شريط كريستال طويل يلتف كالموجة، مصمم ليمتد فوق طاولات الطعام وجزر المطبخ. مصوّرة في معرضنا في حولي مع التوصيل لجميع مناطق الكويت. تواصل معنا عبر واتساب للمقاسات والألوان.', 'A long crystal band twisting like a wave; designed to run along dining tables and kitchen islands.', 'شريط كريستال طويل يلتف كالموجة، مصمم ليمتد فوق طاولات الطعام وجزر المطبخ.', 'https://yubebbfsmlopmnluajgf.supabase.co/storage/v1/object/public/product-images/chandeliers/crystal-wave-linear.jpg'),
('MCH-21', 'chrome-linked-oval-crystal-linear-chandelier', 'Chrome Linked Oval Crystal Linear Chandelier', 'ثريا خطية كروم بحلقات بيضاوية كريستال', 40.000, 24.000, 'Chrome oval links edged in crystal, joined into a long linear chandelier for dining tables and long halls. Photographed in our showroom in Hawalli; delivery across Kuwait. Ask us on WhatsApp for sizes and finishes.', 'حلقات بيضاوية من الكروم بحواف كريستال متصلة في ثريا خطية طويلة لطاولات الطعام والصالات الطويلة. مصوّرة في معرضنا في حولي مع التوصيل لجميع مناطق الكويت. تواصل معنا عبر واتساب للمقاسات والألوان.', 'Chrome oval links edged in crystal, joined into a long linear chandelier for dining tables and long halls.', 'حلقات بيضاوية من الكروم بحواف كريستال متصلة في ثريا خطية طويلة لطاولات الطعام والصالات الطويلة.', 'https://yubebbfsmlopmnluajgf.supabase.co/storage/v1/object/public/product-images/chandeliers/chrome-linked-oval-linear.jpg');

INSERT INTO public.products (sku, slug, name_en, name_ar, base_price, sale_price, category_id, description_en, description_ar,
  short_description_en, short_description_ar, stock_quantity, low_stock_threshold, is_active, is_bestseller, is_featured, is_new)
SELECT o.sku, o.slug, o.name_en, o.name_ar, o.base_price, o.sale_price, c.id, o.description_en, o.description_ar,
  o.short_en, o.short_ar, 9999, 0, true, false, true, true
FROM chandelier_offer o JOIN public.categories c ON c.slug = 'chandelier'
WHERE NOT EXISTS (SELECT 1 FROM public.products p WHERE p.sku = o.sku);

UPDATE public.products p
SET base_price = o.base_price, sale_price = o.sale_price, is_active = true
FROM chandelier_offer o WHERE p.sku = o.sku;

INSERT INTO public.product_images (product_id, url, is_primary, sort_order, alt_text_en, alt_text_ar)
SELECT p.id, o.image_url, true, 0, o.name_en, o.name_ar
FROM chandelier_offer o JOIN public.products p ON p.sku = o.sku
WHERE NOT EXISTS (SELECT 1 FROM public.product_images pi WHERE pi.product_id = p.id);

COMMIT;
